const input = $input.item.json;
const now = new Date();

const firstOfThisMonthUTC = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1);
const firstOfLastMonth = new Date(firstOfThisMonthUTC);
firstOfLastMonth.setUTCMonth(firstOfLastMonth.getUTCMonth() - 1);
const lastOfLastMonth = new Date(firstOfThisMonthUTC - 86400000);

function ymd(d) { return d.toISOString().slice(0, 10); }

const monthLabel = new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(firstOfLastMonth);

return [{ json: {
  ...input,
  reportPeriodStart: ymd(firstOfLastMonth),
  reportPeriodEnd: ymd(lastOfLastMonth),
  monthLabel,
  reportingRegistrySheetId: '1nZm1FLROmGQLyDm4T0p_Lli6WQYzJ6zHDJ2IsoEaWKs',
  clientsTabName: 'Clients',
  driveRootFolderId: '1U3BZHyNU-G1DNHN-picZkZAEXHaO66sW',
  reportsFromEmail: 'onboarding@resend.dev',
} }];

const items = $input.all();
const first = items[0].json;
const list = Array.isArray(first) ? first : [first];
const tenantId = list[0] ? list[0].tenantId : null;
const prior = $('Compute Report Period').item.json;
return [{ json: {
  ...prior,
  xeroTenantId: tenantId,
} }];

const resp = $input.item.json;
const prior = $('Extract Tenant ID + Reporting Config').item.json;
const recs = (resp.body || resp).records || [];
if (resp.statusCode && resp.statusCode >= 300) throw new Error('Monthly Reporting: could not read Airtable My Clients (' + resp.statusCode + ')');
const list = (s) => String(s || '').split(/[,;\n]/).map((x) => x.trim()).filter(Boolean);
return recs.map((r) => { const f = r.fields; return { json: {
  clientId: f['Client ID'], clientName: f['Client name'],
  contactEmail: f['Is demo/test'] ? 'khan.bilalbk408@gmail.com' : (list(f['Report recipients'])[0] || f['Contact email'] || ''),
  usesPhoneBooking: !!f['Phone on'], usesInvoiceAutomation: !!f['Invoicing on'], usesCollections: false, usesQuoting: !!f['Quotes on'],
  jobsSheetId: f['Jobs sheet ID'] || '', jobsSheetTabName: f['Jobs sheet tab'] || 'Jobs',
  reportingSheetId: f['Call log sheet ID'] || '', callLogTabName: 'CallLog',
  xeroTenantId: f['Xero organisation ID'] && !/^DEMO-/.test(f['Xero organisation ID']) ? f['Xero organisation ID'] : prior.xeroTenantId,
  driveRootFolderId: prior.driveRootFolderId, reportsFromEmail: f['From email'] || prior.reportsFromEmail,
  monthLabel: prior.monthLabel, reportPeriodStart: prior.reportPeriodStart, reportPeriodEnd: prior.reportPeriodEnd, testMode: false,
} }; }).filter((x) => x.json.clientId);

const client = $input.item.json;
const v = client.valueStats || {};
return { json: { ...client, callsAnswered: v.aiCallsHandled || 0, bookingsMade: v.aiBookings || 0, quotesGiven: v.quotesDrafted || 0, invoicesSent: v.aiInvoicesDrafted || 0, cashJobs: 0, invoiceReferencesToCheck: [] } };

const client = $input.item.json;

let invoicesChased = 0;
let invoicesPaid = 0;

if (client.usesCollections && Array.isArray(client.invoiceReferencesToCheck) && client.invoiceReferencesToCheck.length) {
  for (const ref of client.invoiceReferencesToCheck) {
    try {
      const invResp = await this.helpers.httpRequestWithAuthentication.call(this, 'xeroOAuth2Api', {
        method: 'GET',
        url: 'https://api.xero.com/api.xro/2.0/Invoices',
        qs: { where: `Reference=="${ref}"` },
        headers: { 'xero-tenant-id': client.xeroTenantId, 'Accept': 'application/json' },
        json: true,
      });
      const invoice = (invResp.Invoices || [])[0];
      if (!invoice) continue;

      const histResp = await this.helpers.httpRequestWithAuthentication.call(this, 'xeroOAuth2Api', {
        method: 'GET',
        url: `https://api.xero.com/api.xro/2.0/Invoices/${invoice.InvoiceID}/History`,
        headers: { 'xero-tenant-id': client.xeroTenantId, 'Accept': 'application/json' },
        json: true,
      });
      const records = histResp.HistoryRecords || [];
      const wasChased = records.some(r => /COLLECTIONS_STAGE=\d/.test(String(r.Details || '')));
      if (wasChased) {
        invoicesChased += 1;
        if (Number(invoice.AmountDue) === 0) invoicesPaid += 1;
      }
    } catch (err) {
      // One invoice failing to fetch shouldn't break this client's whole report - skip and continue.
    }
  }
}

const { invoiceReferencesToCheck, ...rest } = client;
return { json: { ...rest, invoicesChased, invoicesPaid } };

const c = $input.item.json;

function plural(n, s) { return n === 1 ? s : s + 's'; }

const parts = [];

if (c.usesPhoneBooking) {
  if (c.callsAnswered > 0) {
    parts.push(`This month, we answered ${c.callsAnswered} ${plural(c.callsAnswered, 'call')} on your behalf, resulting in ${c.bookingsMade} booked ${plural(c.bookingsMade, 'job')}.`);
  } else {
    parts.push(`We didn't receive any calls on your behalf this month.`);
  }
  if (c.usesQuoting) {
    if (c.quotesGiven > 0) {
      parts.push(`We also provided ${c.quotesGiven} ${plural(c.quotesGiven, 'quote')} over the phone.`);
    } else {
      parts.push(`We didn't provide any phone quotes this month.`);
    }
  }
}

if (c.usesInvoiceAutomation) {
  if (c.invoicesSent > 0) {
    parts.push(`We prepared ${c.invoicesSent} ${plural(c.invoicesSent, 'invoice')} in Xero for you this month.`);
  } else {
    parts.push(`We didn't have any invoices to prepare this month.`);
  }
  if (c.usesCollections) {
    if (c.invoicesChased > 0) {
      parts.push(`Of those, ${c.invoicesChased} needed a collections follow-up, and we successfully chased ${c.invoicesPaid} of them to full payment.`);
    } else {
      parts.push(`None of your invoices needed a collections follow-up this month.`);
    }
  }
  if (c.cashJobs > 0) {
    parts.push(`Separately, ${c.cashJobs} ${plural(c.cashJobs, 'job')} ${c.cashJobs === 1 ? 'was' : 'were'} paid in cash and logged directly.`);
  }
}

const v = c.valueStats || {};
const valueLines = [];
if (v.aiInvoicesDrafted) valueLines.push('- ' + v.aiInvoicesDrafted + ' draft ' + plural(v.aiInvoicesDrafted, 'invoice') + ' prepared in Xero for your approval');
if (v.invoicesCaughtForReview) valueLines.push('- ' + v.invoicesCaughtForReview + ' ' + plural(v.invoicesCaughtForReview, 'job') + ' with messy data caught and checked before invoicing');
if (v.aiCallsHandled) valueLines.push('- ' + v.aiCallsHandled + ' ' + plural(v.aiCallsHandled, 'call') + ' handled by your AI assistant, ' + (v.aiBookings || 0) + ' booked or moved');
if (v.urgentEscalated) valueLines.push('- ' + v.urgentEscalated + ' urgent ' + plural(v.urgentEscalated, 'call') + ' escalated to you straight away');
if (v.quotesDrafted) valueLines.push('- ' + v.quotesDrafted + ' ' + plural(v.quotesDrafted, 'quote') + ' drafted');
if (v.issuesAutoFixed) valueLines.push('- ' + v.issuesAutoFixed + ' ' + plural(v.issuesAutoFixed, 'issue') + ' fixed automatically');
if (valueLines.length) parts.push('\n\nWhat Keystone did for you:\n' + valueLines.join('\n') + (v.hoursSaved ? '\n\nThat is about ' + v.hoursSaved + ' hours of admin time saved (roughly £' + Math.round(v.hoursSaved * 28) + ' at £28/hour).' : ''));
const bodyIntro = `Here's your Keystone performance summary for ${c.monthLabel}.`;
const bodyMiddle = parts.length ? parts.join(' ') : `We didn't have any activity to report for you this month.`;
const bodyOutro = `If you have any questions about this report, just get in touch.\n\nThanks for being a Keystone client.`;

const reportBodyText = `Hi ${c.clientName} team,\n\n${bodyIntro}\n\n${bodyMiddle}\n\n${bodyOutro}`;
const reportSubject = `Your Keystone Performance Report \u2014 ${c.monthLabel}`;

return { json: { ...c, reportSubject, reportBodyText } };

const resp = $input.item.json;
const prior = $('Has Contact Email?').item.json;
return { json: { ...prior, emailSent: true, emailMessageId: resp.id || null } };

const resp = $input.item.json;
const files = resp.files || [];
return { json: { ...$('Report Email Handled').item.json, existingFolderId: files.length ? files[0].id : null } };

const resp = $input.item.json;
const prior = $('Folder Resolved').item.json;
return { json: { ...prior, reportFileId: resp.id } };

